-- 29a55788 English: All original results, preserving nil positions and return count.
[2630] = "Todos os resultados originais, preservando as posições nil e a quantidade de retornos.",
-- c7e69e75 English: Apply the legacy integer or canonical numeric-string spelling test. Numbers use
--     floor equality; strings must equal the spelling obtained after numeric conversion and floor.
--     Other types return false. This is not a finite-number validator.
[2631] = "Aplica o teste antigo de inteiro ou de grafia canônica de texto numérico. Números usam igualdade após arredondamento para baixo; textos devem ser iguais à grafia obtida após a conversão numérica e o arredondamento para baixo. Outros tipos retornam false. Isto não é um validador de números finitos.",
-- 69eb2e21 English: Arguments forwarded unchanged to the observed function.
[2632] = "Argumentos repassados sem alteração para a função observada.",
-- 1d513028 English: Arguments forwarded unchanged; types, identity, arity and nil positions
--     distinguish cache entries.
[2633] = "Argumentos repassados sem alteração; tipos, identidade, aridade e posições nil distinguem as entradas do cache.",
-- 3e8d2702 English: Availability or query-validation reason for a nil level observation.
[2634] = "Motivo de disponibilidade ou de validação da consulta para uma observação de nível nil.",
-- e2ffe9af English: Availability or query-validation reason for a nil level.
[2635] = "Motivo de disponibilidade ou de validação da consulta para um nível nil.",
-- 66134514 English: Availability or query-validation reason when no current state can be read.
[2636] = "Motivo de disponibilidade ou de validação da consulta quando nenhum estado atual pode ser lido.",
-- 77b92c6d English: Availability or query-validation reason when the whole observation is
--     unavailable.
[2637] = "Motivo de disponibilidade ou de validação da consulta quando a observação inteira está indisponível.",
-- 11483c22 English: Availability or validation reason for a nil result.
[2638] = "Motivo de disponibilidade ou de validação para um resultado nil.",
-- bd62d347 English: Availability or validation reason when the record is nil.
[2639] = "Motivo de disponibilidade ou de validação quando o registro é nil.",
-- cab01ca9 English: Availability or validation reason when the result is nil.
[2640] = "Motivo de disponibilidade ou de validação quando o resultado é nil.",
-- 37cddc45 English: Availability reason for a nil result.
[2641] = "Motivo de disponibilidade para um resultado nil.",
-- eced4849 English: Availability reason when resolution fails; nil on success.
[2642] = "Motivo de disponibilidade quando a resolução falha; nil em caso de sucesso.",
-- 09403547 English: Cache an observation after it returns a non-nil value; retry observations whose
--     entire return tuple is nil. Uses the same exact argument keys as getCached.
[2643] = "Guarda uma observação em cache depois que ela retorna um valor não nil; tenta de novo as observações cuja tupla de retorno inteira é nil. Usa as mesmas chaves de argumentos exatas que getCached.",
-- ec80f70e English: Calculate a checked health-history rate using an explicit finite window and
--     clock. Preserve ordered weighting, per-row live canonical rounding, skipped streams, array
--     holes, fractional keys and final visited ages. A fixed 4096-unit budget covers visited rows
--     and accumulation bins across both streams; excess or invalid consumed arithmetic returns
--     unavailable, never a partial estimate or clamp. This new API has its own source identity;
--     historical trend functions remain unchanged.
[2644] = "Calcula uma taxa verificada do histórico de vida usando uma janela e um relógio finitos explícitos. Preserva a ponderação ordenada, o arredondamento canônico ao vivo por linha, os fluxos ignorados, os buracos de arrays, as chaves fracionárias e as idades finais percorridas. Um orçamento fixo de 4096 unidades cobre as linhas percorridas e os contêineres de acumulação dos dois fluxos; excesso ou aritmética consumida inválida retorna indisponível, nunca uma estimativa parcial ou um valor limitado. Esta nova API tem a própria identidade de código; as funções históricas de tendência não mudam.",
-- e3a904cc English: Call an observation once per cache and exact argument tuple, including nil
--     results. Pass the evaluation cache to share observations within a recommendation cycle; nil
--     cache calls directly.
[2645] = "Chama uma observação uma vez por cache e tupla exata de argumentos, incluindo resultados nil. Passe o cache de avaliação para compartilhar observações dentro de um ciclo de recomendação; com cache nil a chamada é direta.",
-- cb8a709c English: Callback invoked after changing the selected unit.
[2646] = "Callback invocado após alterar a unidade selecionada.",
-- f4755bc2 English: Callback receiving the committed spell value.
[2647] = "Callback que recebe o valor de feitiço confirmado.",
-- 8473e032 English: Caller-owned evaluation observation cache; nil queries afresh.
[2648] = "Cache de observações de avaliação pertencente a quem chama; nil consulta novamente.",
-- d07ec966 English: Capability or clock observation availability reason.
[2649] = "Motivo de disponibilidade da capacidade ou da observação do relógio.",
-- aca2f51b English: Capability or observation availability reason for a nil class.
[2650] = "Motivo de disponibilidade da capacidade ou da observação para uma classe nil.",
-- fb8dd5ac English: Check whether a spell can be recommended now, allowing a spell whose remaining
--     cooldown ends with the current global cooldown. On Retail and Forever, where cooldown times
--     are secret in combat, readiness comes from the never-secret isEnabled, isActive and isOnGCD
--     flags instead. This checks cooldown readiness only; it does not check learned status, range
--     or resource usability. Pass evaluation time from evalStart or GetTime().
[2651] = "Verifica se um feitiço pode ser recomendado agora, permitindo um feitiço cujo tempo de recarga restante termina junto com o tempo de recarga global atual. No Retail e no Forever, onde os tempos de recarga são secretos em combate, a prontidão vem das flags isEnabled, isActive e isOnGCD, que nunca são secretas. Verifica apenas a prontidão do tempo de recarga; não verifica se o feitiço foi aprendido, o alcance nem se há recursos para usá-lo. Passe o tempo de avaliação a partir de evalStart ou GetTime().",
-- 1081f5fc English: Check whether a table has a non-nil value at a key. A stored false value still
--     counts as present; this does not scan table values.
[2652] = "Verifica se uma tabela tem um valor não nil em uma chave. Um valor false armazenado conta como presente; isto não percorre os valores da tabela.",
-- 3f1a5911 English: Checkbox widget with boolean value and callback methods.
[2653] = "Widget de caixa de seleção com valor booleano e métodos de callback.",
-- 8373609b English: Choose the supplied player value only for the literal player unit token; every
--     other unit selects the nonplayer value. Selected false and nil values are preserved.
[2654] = "Escolhe o valor de jogador fornecido apenas para o token de unidade literal player; qualquer outra unidade seleciona o valor de não jogador. Os valores false e nil selecionados são preservados.",
-- 68e9defe English: Classification, validation or availability reason for a nil result.
[2655] = "Motivo de classificação, validação ou disponibilidade para um resultado nil.",
-- 7fc7159a English: Classify a numeric item as a glyph for the requested class, using guarded
--     native item metadata. Class is optional and defaults to the readable player class. This
--     establishes item classification only, not equipped status or an item-to-glyph-spell ID
--     mapping.
[2656] = "Classifica um item numérico como glifo da classe solicitada, usando metadados de item nativos protegidos. A classe é opcional e, por padrão, é a classe legível do jogador. Isso estabelece apenas a classificação do item, não se está equipado nem um mapeamento de item para ID de feitiço de glifo.",
-- 355b4c25 English: Client-family, query-validation or required-observation availability reason for
--     a nil result.
[2657] = "Motivo de disponibilidade da família de cliente, da validação da consulta ou de uma observação necessária para um resultado nil.",
-- 56d0a810 English: Client-policy, capability, call or observation availability reason for a nil
--     form.
[2658] = "Motivo de disponibilidade da política do cliente, da capacidade, da chamada ou da observação para uma forma nil.",
-- fffddfca English: Client-policy, capability, call or observation availability reason for a nil
--     record.
[2659] = "Motivo de disponibilidade da política do cliente, da capacidade, da chamada ou da observação para um registro nil.",
-- 7a0f627b English: Client-policy, native-call or required membership availability reason for a nil
--     record.
[2660] = "Motivo de disponibilidade da política do cliente, da chamada nativa ou da participação necessária para um registro nil.",
-- 0a8d99a6 English: Closed kind: runner, resist or immune.
[2661] = "Tipo fechado: runner, resist ou immune.",
-- 6999f76c English: Closed scalar kind: current or maximum.
[2662] = "Tipo escalar fechado: current ou maximum.",
-- a7224c57 English: Collect table keys and sort them by their associated values using Lua less-than
--     comparison. This sorts values rather than key names; equal values have no guaranteed key
--     order.
[2663] = "Coleta as chaves de uma tabela e as ordena pelos valores associados usando a comparação menor que do Lua. Ordena os valores, não os nomes das chaves; valores iguais não têm ordem de chaves garantida.",
-- 508c105b English: Combat-policy, capability, observation or scan-budget reason for a nil count.
[2664] = "Motivo da política de combate, da capacidade, da observação ou do orçamento de varredura para uma contagem nil.",
-- 14b9d8a2 English: Combined signed weighted rate from the original formula; malformed or nonfinite
--     inputs retain the legacy error/numeric behavior.
[2665] = "Taxa ponderada combinada com sinal da fórmula original; entradas malformadas ou não finitas mantêm o comportamento antigo de erro/numérico.",
-- ee842735 English: Compare the selected unit creature ID with one existing saved creature-type
--     key. Resolve the fixed key-to-ID identity in one private executable mapper; gameplay matching
--     does not depend on the mutable localized UI caption map. Share complete native observations
--     within the supplied evaluation-pass cache by actual observer, receiver and unit, including
--     absence and unavailable reasons. Known absence or a known different ID returns false; an
--     unavailable required observation returns nil with a reason. No longterm state or caption
--     mutation is added.
[2666] = "Compara o ID de criatura da unidade selecionada com uma chave de tipo de criatura salva existente. Resolve a identidade fixa de chave para ID em um único mapeador executável privado; a correspondência no jogo não depende do mapa mutável de legendas localizadas da interface. Compartilha observações nativas completas dentro do cache da passada de avaliação fornecido, por observador, receptor e unidade reais, incluindo ausência e motivos de indisponibilidade. Uma ausência conhecida ou um ID diferente conhecido retorna false; uma observação necessária indisponível retorna nil com um motivo. Nenhum estado de longo prazo nem alteração de legendas é adicionado.",
-- 098e89f6 English: Compare two exact unit tokens using UnitIsUnit after checking only the first
--     token with UnitExists. A readable absent first unit returns false without comparing. Required
--     missing, failed, restricted or malformed observations return nil with a reason. No second
--     existence query, GUID lookup or inferred identity is added.
[2667] = "Compara dois tokens de unidade exatos usando UnitIsUnit após verificar apenas o primeiro token com UnitExists. Uma primeira unidade ausente de forma legível retorna false sem comparar. Observações necessárias ausentes, com falha, restritas ou malformadas retornam nil com um motivo. Nenhuma segunda consulta de existência, busca de GUID ou identidade deduzida é adicionada.",
-- f92fafbd English: Compare two values using an RM operator identifier: LESSTHAN, LESSTHANOREQUALS,
--     GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS or DIVISIBLE. Invalid operators warn and
--     return nil; operands must support the selected Lua operation.
[2668] = "Compara dois valores usando um identificador de operador do RM: LESSTHAN, LESSTHANOREQUALS, GREATERTHAN, GREATERTHANOREQUALS, EQUALS, NOTEQUALS ou DIVISIBLE. Operadores inválidos geram um aviso e retornam nil; os operandos precisam suportar a operação Lua selecionada.",
-- 4d1da429 English: Comparison operator key, such as EQUALS or LESSTHAN.
[2669] = "Chave do operador de comparação, como EQUALS ou LESSTHAN.",
-- 8d6dc0da English: Comparison result, or nil for an unknown operator.
[2670] = "Resultado da comparação, ou nil para um operador desconhecido.",
-- 45e7a5a6 English: Comparison text retaining named Boolean alternative markup.
[2671] = "Texto de comparação que mantém a marcação de alternativas booleanas nomeadas.",
-- beb1fd9a English: Complete matching class count, including zero, or nil when unavailable.
[2672] = "Contagem completa de classes correspondentes, incluindo zero, ou nil quando indisponível.",
-- 3abb0dce English: Complete nonnegative observed count including zero, or nil when unavailable.
[2673] = "Contagem observada completa não negativa, incluindo zero, ou nil quando indisponível.",
-- a3cbc46a English: Condition container supporting SetLayout, AddChild, SetUserData, SetWidth and
--     DoLayout.
[2674] = "Contêiner de condição com suporte a SetLayout, AddChild, SetUserData, SetWidth e DoLayout.",
-- 1edda05a English: Condition value record containing spell, ranked and disabled fields; updated in
--     place.
[2675] = "Registro de valores da condição com os campos spell, ranked e disabled; atualizado no próprio lugar.",
-- bd948209 English: Condition value record updated when a unit is chosen.
[2676] = "Registro de valores da condição atualizado quando uma unidade é escolhida.",
-- 49082497 English: Configured unit selector; add it with parent:AddChild(widget).
[2677] = "Seletor de unidade configurado; adicione-o com parent:AddChild(widget).",
-- 93e87554 English: Copy a table using tostring of each original key as the destination key. Values
--     retain their original identities. Colliding stringified keys overwrite each other in
--     unspecified pairs traversal order.
[2678] = "Copia uma tabela usando tostring de cada chave original como chave de destino. Os valores mantêm as identidades originais. Chaves que colidem ao virar texto se sobrescrevem na ordem não especificada de percurso de pairs.",
-- dcd01801 English: Count all entries visited by pairs, including false values and sparse numeric
--     or nonnumeric keys. A nil table has length zero.
[2679] = "Conta todas as entradas percorridas por pairs, incluindo valores false e chaves numéricas esparsas ou não numéricas. Uma tabela nil tem comprimento zero.",
-- 7ee6eac7 English: Count matching class tokens in the current fixed roster. Read group membership
--     first; when requested, raid membership selects raid1 through raid40 without a separate player
--     fact. Solo and party paths read player first, then party1 through party4 when grouped. A
--     complete known roster returns a count, including zero; any required unavailable fact returns
--     nil with a reason. Complete observations share the evaluation-pass cache; no player class
--     persists across passes. Archived raw callbacks retain their original load-time class
--     separately.
[2680] = "Conta os tokens de classe correspondentes na lista fixa atual. Lê primeiro a participação no grupo; quando solicitado, a participação na raide seleciona de raid1 a raid40 sem um dado separado do jogador. Os caminhos solo e de grupo leem primeiro o jogador e depois de party1 a party4 quando agrupado. Uma lista conhecida completa retorna uma contagem, incluindo zero; qualquer dado necessário indisponível retorna nil com um motivo. Observações completas compartilham o cache da passada de avaliação; nenhuma classe de jogador persiste entre passadas. Callbacks brutos arquivados mantêm separadamente a classe original do momento do carregamento.",
-- ddfd3a7c English: Count only GUID-keyed units already in the observed membership snapshot. Verify
--     current token identity before using the published threat observer; known absent or reused
--     tokens are excluded without adding replacements. Complete identity and threat observations
--     share only the supplied evaluation cache, while membership is traversed fresh. Known nonenemy
--     or optional nil threat is not counted; required unreadable, malformed or failed facts make
--     the entire result unavailable. This does not enumerate a complete roster, apply a range
--     filter or modify tracked records.
[2681] = "Conta apenas as unidades indexadas por GUID que já estão no instantâneo de participação observado. Verifica a identidade do token atual antes de usar o observador de ameaça publicado; tokens sabidamente ausentes ou reutilizados são excluídos sem adicionar substitutos. As observações completas de identidade e ameaça compartilham apenas o cache de avaliação fornecido, enquanto a participação é percorrida novamente. Não inimigos conhecidos ou ameaça opcional nil não são contados; dados necessários ilegíveis, malformados ou com falha deixam o resultado inteiro indisponível. Isso não enumera uma lista completa, não aplica filtro de alcance nem modifica os registros rastreados.",
-- 02e149c6 English: Create a condition field container with RM-owned List, Table and responsive
--     spell-field layouts. It accepts registered native condition widgets; add children with
--     AddChild and attach the group to the callback parent.
[2682] = "Cria um contêiner de campos de condição com layouts de Lista, Tabela e campo de feitiço responsivo próprios do RM. Ele aceita widgets de condição nativos registrados; adicione filhos com AddChild e anexe o grupo ao pai do callback.",
-- 24b26357 English: Create a configured unit selector bound to a condition value record. Returns
--     the widget for the caller to add to the condition callback parent.
[2683] = "Cria um seletor de unidade configurado vinculado a um registro de valores de condição. Retorna o widget para quem chama adicioná-lo ao pai do callback da condição.",
-- 704feebd English: Create a native boolean condition control. Configure SetLabel, SetValue,
--     SetDisabled and OnValueChanged; add it with parent:AddChild(widget).
[2684] = "Cria um controle booleano de condição nativo. Configure SetLabel, SetValue, SetDisabled e OnValueChanged; adicione-o com parent:AddChild(widget).",
-- d67fc3b8 English: Create a native button using the shared condition widget lifecycle and
--     workbench theme. SetText, SetDisabled and SetCallback configure its label and interaction;
--     OnClick receives the mouse button. Add it to the callback parent with
--     parent:AddChild(widget).
[2685] = "Cria um botão nativo usando o ciclo de vida compartilhado dos widgets de condição e o tema da bancada. SetText, SetDisabled e SetCallback configuram o rótulo e a interação; OnClick recebe o botão do mouse. Adicione-o ao pai do callback com parent:AddChild(widget).",
-- d4341110 English: Create a native condition selector. SetList accepts key-to-label or
--     key-to-entry maps; SetValue selects a key and OnValueChanged reports changes. Add it with
--     parent:AddChild(widget).
[2686] = "Cria um seletor de condição nativo. SetList aceita mapas de chave para rótulo ou de chave para entrada; SetValue seleciona uma chave e OnValueChanged informa as alterações. Adicione-o com parent:AddChild(widget).",
-- e149229e English: Create a native image control using the condition widget lifecycle. SetImage
--     and SetImageSize choose the texture; SetText optionally adds a caption. OnClick, OnEnter and
--     OnLeave use the shared callback contract. Add the control to the callback parent with
--     parent:AddChild(widget).
[2687] = "Cria um controle de imagem nativo usando o ciclo de vida dos widgets de condição. SetImage e SetImageSize escolhem a textura; SetText adiciona opcionalmente uma legenda. OnClick, OnEnter e OnLeave usam o contrato de callbacks compartilhado. Adicione o controle ao pai do callback com parent:AddChild(widget).",
-- b943d164 English: Create a native numeric condition input with a slider and typed numeric field.
--     Configure SetSliderValues, SetValue, SetIsPercent and SetCallback; OnValueChanged reports
--     committed values. Add it with parent:AddChild(widget).
[2688] = "Cria uma entrada numérica de condição nativa com um controle deslizante e um campo numérico tipado. Configure SetSliderValues, SetValue, SetIsPercent e SetCallback; OnValueChanged informa os valores confirmados. Adicione-a com parent:AddChild(widget).",
-- a67c621c English: Create a native position pad using the shared directional controls.
--     OnOffsetChanged reports horizontal and vertical direction, whether Center was pressed, and
--     the increment (one, or ten with Shift). SetDisabled controls interaction; add the pad to the
--     callback parent with parent:AddChild(widget).
[2689] = "Cria um painel de posição nativo usando os controles direcionais compartilhados. OnOffsetChanged informa a direção horizontal e vertical, se Centralizar foi pressionado e o incremento (um, ou dez com Shift). SetDisabled controla a interação; adicione o painel ao pai do callback com parent:AddChild(widget).",
-- 25defe9e English: Create a native text input using the condition widget contract. SetLabel,
--     SetText, SetDisabled and SetCallback configure it; OnEnterPressed commits text. Add it to the
--     callback parent with parent:AddChild(widget).
[2690] = "Cria uma entrada de texto nativa usando o contrato dos widgets de condição. SetLabel, SetText, SetDisabled e SetCallback a configuram; OnEnterPressed confirma o texto. Adicione-a ao pai do callback com parent:AddChild(widget).",
-- edff3bd0 English: Create a shallow filtered copy despite the historical deepcopy name. Nested
--     values retain their original identities and the source metatable is not copied. By default
--     exclude keys listed among except values; invert true includes only listed keys. Nil input
--     returns nil.
[2691] = "Cria uma cópia filtrada rasa, apesar do nome histórico deepcopy. Os valores aninhados mantêm as identidades originais e a metatabela de origem não é copiada. Por padrão, exclui as chaves listadas entre os valores de except; invert true inclui apenas as chaves listadas. Uma entrada nil retorna nil.",
-- ccc11c66 English: Create a spell input with suggestions, validation and spell-link support for
--     custom condition widgets. The update callback owns saving a chosen value; add the returned
--     widget to the callback parent.
[2692] = "Cria uma entrada de feitiço com sugestões, validação e suporte a links de feitiço para widgets de condições personalizadas. O callback de atualização é responsável por salvar o valor escolhido; adicione o widget retornado ao pai do callback.",
-- 4736bce4 English: Create a transient named condition summary. Use {name} for scalar values and
--     {{positive|negative}} for predicate alternatives; prefix a primary alternative with !. Escape
--     literal double braces as {{{{ and }}}}. Values are inserted literally without parsing their
--     percent signs, links, colors or braces. Typed predicate values participate in primary
--     selection. Templates, values and rendered text are bounded; malformed input renders a
--     localized unavailable summary. This changes presentation only and runs no condition
--     observations.
[2693] = "Cria um resumo de condição nomeado transitório. Use {name} para valores escalares e {{positive|negative}} para alternativas de predicado; coloque ! antes de uma alternativa principal. Escape chaves duplas literais como {{{{ e }}}}. Os valores são inseridos literalmente, sem analisar sinais de porcentagem, links, cores ou chaves. Valores de predicado tipados participam da seleção principal. Modelos, valores e texto renderizado são limitados; uma entrada malformada exibe um resumo localizado de indisponível. Isso altera apenas a apresentação e não executa observações de condições.",
-- 7735b638 English: Create a typed comparison predicate for a named condition phrase. Positive
--     wording uses the original captured operator map and negative wording uses the current negated
--     operator map. A primary predicate takes precedence over qualifiers; only the first eligible
--     predicate negates. Unknown operators use the existing operator placeholder. This formats
--     wording without comparing values or evaluating a condition.
[2694] = "Cria um predicado de comparação tipado para uma frase de condição nomeada. A redação positiva usa o mapa de operadores original capturado e a negativa usa o mapa de operadores negados atual. Um predicado principal tem precedência sobre os qualificadores; apenas o primeiro predicado elegível é negado. Operadores desconhecidos usam o marcador de operador existente. Isso formata a redação sem comparar valores nem avaliar uma condição.",
-- ddea308b English: Create an iterator over a sorted snapshot of table keys. Default ordering
--     compares keys; a custom order callback receives the original table and two keys. Values are
--     read from the original table when each key is yielded. The legacy iterator ends when the next
--     captured key is nil or false.
[2695] = "Cria um iterador sobre um instantâneo ordenado das chaves de uma tabela. A ordem padrão compara as chaves; um callback de ordem personalizado recebe a tabela original e duas chaves. Os valores são lidos da tabela original quando cada chave é produzida. O iterador antigo termina quando a próxima chave capturada é nil ou false.",
-- 629b2567 English: Create native wrapping text that measures its height from its width and font.
--     SetText, SetFont or SetFontObject configure its contents. Add it to the callback parent with
--     parent:AddChild(widget) so layout can track its measured height.
[2696] = "Cria texto nativo com quebra de linha que mede a própria altura a partir da largura e da fonte. SetText, SetFont ou SetFontObject configuram o conteúdo. Adicione-o ao pai do callback com parent:AddChild(widget) para que o layout acompanhe a altura medida.",
-- c58c9a9a English: Create native wrapping text with optional leading image and pointer callbacks.
--     SetImage and SetImageSize configure the image; OnEnter, OnLeave and OnClick use the condition
--     callback contract. Add it to the callback parent with parent:AddChild(widget); callbacks
--     expire when its lease is released.
[2697] = "Cria texto nativo com quebra de linha, com imagem inicial opcional e callbacks do ponteiro. SetImage e SetImageSize configuram a imagem; OnEnter, OnLeave e OnClick usam o contrato de callbacks das condições. Adicione-o ao pai do callback com parent:AddChild(widget); os callbacks expiram quando a concessão dele é liberada.",
-- fa988d31 English: Current evaluation time in seconds from GetTime(), normally evalStart.
[2698] = "Momento de avaliação atual em segundos a partir de GetTime(), normalmente evalStart.",
-- c7fd7453 English: Current positive visibility distance in yards; nil when unavailable.
[2699] = "Distância de visibilidade positiva atual em metros; nil quando indisponível.",
-- 574eed72 English: Current unit token whose distance from the player should be observed.
[2700] = "Token da unidade atual cuja distância até o jogador deve ser observada.",
-- 83a1023e English: Damage/heals arrays of time/value rows; only selected streams are consumed.
[2701] = "Arrays de dano/cura com linhas de tempo/valor; apenas os fluxos selecionados são consumidos.",
-- 38e0b44b English: Decimal places, default zero; negative values round to tens or larger powers of
--     ten.
[2702] = "Casas decimais, zero por padrão; valores negativos arredondam para dezenas ou potências de dez maiores.",
-- c1094708 English: Dense array of keys sorted by associated value.
[2703] = "Array denso de chaves ordenadas pelo valor associado.",
-- 7de55bf4 English: Dense array of nonempty text fields.
[2704] = "Array denso de campos de texto não vazios.",
-- ba17b32f English: Destination array modified in place.
[2705] = "Array de destino modificado no próprio lugar.",
-- 9d65688a English: Display lookup table.
[2706] = "Tabela de consulta para exibição.",
-- 763bf095 English: Estimate signed health change from weighted damage and healing history. Damage
--     contributes a negative rate and healing a positive rate. Read the live profile window when no
--     window is supplied, use the live clock and legacy rounding service, and preserve the existing
--     weighting and rounded-age calculation. This helper does not validate or sanitize history,
--     clamp timestamps, or guarantee finite results.
[2707] = "Estima a variação de vida com sinal a partir do histórico ponderado de dano e cura. O dano contribui com uma taxa negativa e a cura com uma positiva. Lê a janela do perfil ao vivo quando nenhuma janela é fornecida, usa o relógio ao vivo e o serviço de arredondamento antigo, e preserva a ponderação existente e o cálculo de idade arredondada. Esta função auxiliar não valida nem higieniza o histórico, não limita marcas de tempo nem garante resultados finitos.",
-- c95e98a7 English: Estimate time until selected health. Cache complete native identity and lazy
--     scalar observations per evaluation pass, while provider, history, window, clock and forecast
--     stay live. Exact target equality returns zero before history work. Preserve deliberate
--     no-estimate false and initialized-zero results for zero or opposite rates; required invalid
--     facts, overflow or 4096-unit work exhaustion are unavailable. Never mutate history or invent
--     a partial estimate.
[2708] = "Estima o tempo até a vida selecionada. Guarda em cache, por passada de avaliação, a identidade nativa completa e as observações escalares preguiçosas, enquanto provedor, histórico, janela, relógio e previsão continuam ao vivo. A igualdade exata com o alvo retorna zero antes do processamento do histórico. Preserva os resultados deliberados false (sem estimativa) e zero inicializado para taxas nulas ou opostas; dados necessários inválidos, estouro ou esgotamento do trabalho de 4096 unidades ficam indisponíveis. Nunca altera o histórico nem inventa uma estimativa parcial.",
-- 52a17c6c English: Evaluation cache, or nil to bypass caching.
[2709] = "Cache de avaliação, ou nil para ignorar o cache.",
-- 79697e3a English: Evaluation-pass cache for complete unit observations; nil observes directly.
--     Different selected keys reuse the same unit snapshot.
[2710] = "Cache da passada de avaliação para observações completas de unidades; nil observa diretamente. Chaves selecionadas diferentes reutilizam o mesmo instantâneo da unidade.",
-- bd88f3f9 English: Evaluation-pass cache, or nil for fresh observations.
[2711] = "Cache da passada de avaliação, ou nil para observações novas.",
-- d022fab6 English: Evaluation-pass cache, or nil to observe identity directly. Resource mapping is
--     resolved live on each invocation.
[2712] = "Cache da passada de avaliação, ou nil para observar a identidade diretamente. O mapeamento de recursos é resolvido ao vivo a cada invocação.",
-- 0900784b English: Evaluation-pass cache, or nil to observe identity directly. Successful player
--     class observations may use the existing longterm identity cache; resource mapping remains
--     live.
[2713] = "Cache da passada de avaliação, ou nil para observar a identidade diretamente. Observações bem-sucedidas da classe do jogador podem usar o cache de identidade de longo prazo existente; o mapeamento de recursos continua ao vivo.",
-- 383aa43c English: Evaluation-pass native observation cache; nil queries afresh.
[2714] = "Cache de observações nativas da passada de avaliação; nil consulta novamente.",
-- bf9ecd5c English: Evaluation-pass presence cache only; name, level and provider history remain
--     fresh.
[2715] = "Apenas cache de presença da passada de avaliação; nome, nível e histórico do provedor continuam atualizados.",
-- 2dbf0453 English: Exact helper-owned player, party1..party4 or raid1..raid40 token.
[2716] = "Token exato pertencente à função auxiliar: player, party1..party4 ou raid1..raid40.",
-- 27bda267 English: Exact integral native rune slot from 1 through 6.
[2717] = "Espaço de runa nativo inteiro exato, de 1 a 6.",
-- 4fc2d3d1 English: Exact nonempty unit token to observe.
[2718] = "Token de unidade exato e não vazio a observar.",
-- c590f11f English: Exact nonempty unit token, passed unchanged.
[2719] = "Token de unidade exato e não vazio, passado sem alterações.",
-- fd8065c0 English: Exact readable recipient name recorded for this cast.
[2720] = "Nome exato e legível do destinatário registrado para este lançamento.",
-- b05cf3b2 English: Exact selected unit token; only the literal player token may select the TBC
--     combo transport.
[2721] = "Token de unidade selecionado exato; apenas o token literal player pode selecionar o transporte de combo do TBC.",
-- 19306e82 English: Exact selected unit token; player class alone may use the successful longterm
--     cache.
[2722] = "Token de unidade selecionado exato; apenas a classe do jogador pode usar o cache de longo prazo de observações bem-sucedidas.",
-- af7eabaa English: Exact selected unit token; the attacker remains player.
[2723] = "Token de unidade selecionado exato; o atacante continua sendo player.",
-- c08ce58e English: Exact unit token checked for existence and passed to the selected metadata API.
