[2747] = "Estado de ameaça nativo finito, false para ausência conhecida, não inimigo ou sem ameaça, ou nil para observações indisponíveis.",
-- 9cb9f6d2 English: Finite nonnegative native health scalar, or nil when unavailable.
[2748] = "Valor escalar de vida nativo finito e não negativo, ou nil quando indisponível.",
