[2763] = "Registro de histórico com arrays de dano e cura, do mais recente ao mais antigo, com entradas de tempo/valor. Um histórico falso retorna apenas zero sem ler o relógio.",
-- 8deb9947 English: Identifier-keyed scalar values or typed predicates. Strings, finite numbers and
--     booleans are supported; referenced slots must be present. Values are captured when the phrase
--     is created.
[2764] = "Valores escalares ou predicados tipados indexados por identificador. Textos, números finitos e booleanos são suportados; os espaços referenciados precisam estar presentes. Os valores são capturados quando a frase é criada.",
-- b1c195d7 English: Insert each value visited by ipairs at its corresponding leading index in the
--     destination array. Existing entries shift after the inserted prefix; traversal stops at the
--     first missing source index.
[2765] = "Insere cada valor percorrido por ipairs no índice inicial correspondente do array de destino. As entradas existentes são deslocadas após o prefixo inserido; o percurso para no primeiro índice de origem ausente.",
-- db2baa62 English: Integral RM statistic selector 1..5, or 6 for effective armor.
[2766] = "Seletor de atributo do RM inteiro 1..5, ou 6 para a armadura efetiva.",
-- c406e603 English: Iterator yielding a captured key and its current table value, or no values when
