[2767] = "Iterador que produz uma chave capturada e o valor atual dela na tabela, ou nenhum valor quando esgotado.",
-- ce63ac6d English: Key to look up.
[2768] = "Chave a consultar.",
-- 3638b5da English: Known active count from zero through the RM scan budget, or nil when
--     unavailable.
[2769] = "Contagem ativa conhecida, de zero até o orçamento de varredura do RM, ou nil quando indisponível.",
-- 101d17c0 English: Known nonempty role string, false for known absent unit, or nil when
