[2772] = "Presença ou ausência conhecida da unidade; nil quando a observação necessária está indisponível.",
-- 337a2aa3 English: Larger rounded stream age in seconds, not a sample count or proof of continuous
--     observation. Omitted when history is falsy.
[2773] = "Maior idade arredondada do fluxo em segundos; não é uma contagem de amostras nem prova de observação contínua. Omitida quando o histórico é falso.",
-- 289c0861 English: Left operand; use numbers for ordering and divisibility.
[2774] = "Operando esquerdo; use números para ordenação e divisibilidade.",
-- c6b39836 English: Literal prefix, including an empty prefix.
[2775] = "Prefixo literal, incluindo um prefixo vazio.",
-- 8bc05b19 English: Literal suffix, including an empty suffix.
[2776] = "Sufixo literal, incluindo um sufixo vazio.",
-- 696821ba English: Live selected talent-group argument, forwarded unchanged as one argument after
--     readability checking.
[2777] = "Argumento do grupo de talentos selecionado ao vivo, repassado sem alteração como um único argumento após a verificação de legibilidade.",
-- 55c2262c English: Localized complete sentence with named slots and optional explicit predicate
