[2779] = "Consulta uma chave de tabela para exibição, preservando resultados não nil; tabelas inválidas, chaves ausentes e chaves nil usam um texto de marcador nullable.",
-- d27c5ef2 English: Lookup key.
[2780] = "Chave de consulta.",
-- d746509f English: Lua pattern character-class separator, default %s for whitespace.
[2781] = "Separador de classe de caracteres de padrão Lua; por padrão, %s para espaços em branco.",
-- 3aeb0664 English: Mark the positive wording as the primary named alternative.
[2782] = "Marca a redação positiva como a alternativa principal nomeada.",
-- 44dec6d3 English: Matching key, including a false key, or nil when no match exists.
[2783] = "Chave correspondente, incluindo uma chave false, ou nil quando não há correspondência.",
-- 75ef3e00 English: Missing-value display text; omitted uses the localized value placeholder.
[2784] = "Texto exibido quando o valor está ausente; se omitido, usa o marcador de valor localizado.",
-- 15f81670 English: Native button with label, disabled state and lease-protected callbacks.
[2785] = "Botão nativo com rótulo, estado desativado e callbacks protegidos por concessão.",
-- 8eb10f5d English: Native directional pad with center reset and lease-protected callbacks.
[2786] = "Painel direcional nativo com redefinição central e callbacks protegidos por concessão.",
-- bb0ac63a English: Native image control with label, texture, disabled state and callbacks.
[2787] = "Controle de imagem nativo com rótulo, textura, estado desativado e callbacks.",
-- 43cf01e1 English: Native interactive text and image control with measured height and disabled
