[2788] = "Controle nativo interativo de texto e imagem com altura medida e estado desativado.",
-- 990a6544 English: Native one-based integral active-row index within the 256-row RM scan budget.
[2789] = "Índice nativo inteiro, começando em um, da linha ativa dentro do orçamento de varredura de 256 linhas do RM.",
-- 7e3aed01 English: Native wrapping text control with font, color and alignment methods.
[2790] = "Controle de texto nativo com quebra de linha e métodos de fonte, cor e alinhamento.",
-- d76c2067 English: New shallow filtered table, or nil for nil input.
[2791] = "Nova tabela filtrada rasa, ou nil para uma entrada nil.",
-- 50f7bd28 English: New table with stringified keys and unchanged values.
[2792] = "Nova tabela com chaves convertidas em texto e valores inalterados.",
-- f1052f11 English: Newest-first health snapshots containing time, value and max. Falsy input
--     returns only zero without reading the clock.
[2793] = "Instantâneos de vida, do mais recente ao mais antigo, com tempo, valor e máximo. Uma entrada falsa retorna apenas zero sem ler o relógio.",
-- 7276d3c4 English: No return values. The destination array is modified in place.
[2794] = "Sem valores de retorno. O array de destino é modificado no próprio lugar.",
-- 69c24773 English: No return values. The supplied table is modified in place.
[2795] = "Sem valores de retorno. A tabela fornecida é modificada no próprio lugar.",
-- da87cc23 English: Nonempty class filename token to count; no class-token whitelist is applied.
[2796] = "Token de nome de arquivo de classe não vazio a contar; nenhuma lista de permissão de tokens de classe é aplicada.",
-- 3694f9ed English: Nonempty historical school key for resist/immune; unused for runner.
[2797] = "Chave histórica de escola não vazia para resist/immune; não usada para runner.",
-- 7ee44b6f English: Normalized bounded socket snapshot with slots and complete, or nil when the
--     query is unavailable.
[2798] = "Instantâneo normalizado e limitado dos encaixes com slots e complete, ou nil quando a consulta está indisponível.",
-- 93ec5fb4 English: Normalized requested subject with finite timeRemaining or timeRemainingReason;
--     nil when the required row or subject is unavailable.
[2799] = "Assunto solicitado normalizado com timeRemaining finito ou timeRemainingReason; nil quando a linha ou o assunto necessário está indisponível.",
-- 7663ebe1 English: Number of entries visited.
[2800] = "Número de entradas percorridas.",
-- 7f36a397 English: Number or string to inspect; other types do not match.
[2801] = "Número ou texto a inspecionar; outros tipos não correspondem.",
-- 4e6ddf17 English: Numeric widget supporting slider bounds, percent display and pending-edit
--     validation.
[2802] = "Widget numérico com suporte a limites de controle deslizante, exibição de porcentagem e validação de edições pendentes.",
-- c8144d6f English: Observation kind: cast or channel. These use different native interruptibility
--     tuple positions.
[2803] = "Tipo de observação: cast ou channel. Eles usam posições diferentes na tupla nativa de interrompibilidade.",
-- 02905e55 English: Observation, history, work-limit or arithmetic availability reason.
[2804] = "Motivo de disponibilidade da observação, do histórico, do limite de trabalho ou da aritmética.",
-- 966b23c3 English: Observe a fresh protected zero-argument GetTime for a needed health forecast.
--     Require readability and a finite number; preserve signed and fractional values without adding
--     a monotonic, integral or nonnegative restriction. No clock cache or extra native query is
--     used.
[2805] = "Observa um GetTime novo, protegido e sem argumentos para uma previsão de vida necessária. Exige legibilidade e um número finito; preserva valores com sinal e fracionários sem adicionar restrições de monotonia, de inteiros ou de não negativos. Nenhum cache de relógio ou consulta nativa extra é usado.",
-- 9d79dc0d English: Observe a point resource that the client reports in fragments (Mists of
--     Pandaria Burning Embers). Current uses exactly UnitPower(unit,powerType,true) and maximum
--     UnitPowerMax(unit,powerType,true); the result is divided by Blizzard MAX_POWER_PER_EMBER
--     (10), so 35 fragments are 3.5. Probe policy only. Missing, failed, restricted or malformed
--     data remains unavailable; it never falls back to the whole-unit query. No cache is added.
[2806] = "Observa um recurso de pontos que o cliente informa em fragmentos (Brasas Ardentes do Mists of Pandaria). Current usa exatamente UnitPower(unit,powerType,true) e maximum usa UnitPowerMax(unit,powerType,true); o resultado é dividido pelo MAX_POWER_PER_EMBER (10) da Blizzard, então 35 fragmentos são 3,5. Apenas em clientes com política de sondagem. Dados ausentes, com falha, restritos ou malformados continuam indisponíveis; nunca recorre à consulta de unidades inteiras. Nenhum cache é adicionado.",
-- eb0c20b2 English: Observe a readable raw unit level on known clients. A readable absent unit
--     returns exists=false; present units require a positive finite integer UnitLevel. Unknown boss
--     levels, missing, failed, restricted or malformed observations return nil with a reason. This
--     does not use effective or scaled levels.
[2807] = "Observa um nível bruto e legível da unidade em clientes conhecidos. Uma unidade ausente legível retorna exists=false; unidades presentes exigem um UnitLevel inteiro positivo e finito. Níveis de chefe desconhecidos e observações ausentes, com falha, restritas ou malformadas retornam nil com um motivo. Não usa níveis efetivos nem escalonados.",
-- bc5313d0 English: Observe a selected unit role on probe- and restricted-policy clients without
--     issuing inspection requests. Known unit absence returns false. Prefer the callable modern
--     inspection API, with legacy fallback only when that callable is absent; a selected failure
--     never falls through. Require a positive finite integral specialization ID and consume only
--     role return five from the exact one-argument GetSpecializationInfoByID call. Missing, failed,
--     restricted or malformed required facts are unavailable; readable nonempty future role strings
--     remain exact.
[2808] = "Observa a função de uma unidade selecionada em clientes com política de sondagem ou restrita sem emitir solicitações de inspeção. Ausência conhecida da unidade retorna false. Prefere a API de inspeção moderna invocável, com a alternativa antiga apenas quando essa função não existe; uma falha da selecionada nunca passa para a outra. Exige um ID de especialização inteiro, positivo e finito, e consome apenas a função do quinto retorno da chamada exata de um argumento a GetSpecializationInfoByID. Dados necessários ausentes, com falha, restritos ou malformados ficam indisponíveis; textos de função futuros legíveis e não vazios continuam exatos.",
-- 3668cf1e English: Observe a unit casting or channeling on probe- and restricted-policy clients. A
--     known absent unit or a readable inactive result returns active=false. Active records contain
--     name, or nameReason when the name is secret (the unit is still casting), and independently
--     available remainingSeconds, durationSeconds, interruptible and spellID fields, with
--     remainingReason, durationReason, interruptibleReason or spellReason when an optional field is
--     unavailable. Missing, failed or restricted presence observations return nil with a reason.
[2809] = "Observa uma unidade lançando ou canalizando em clientes com política de sondagem ou restrita. Uma unidade sabidamente ausente ou um resultado inativo legível retorna active=false. Registros ativos contêm name, ou nameReason quando o nome é secreto (a unidade continua lançando), e os campos remainingSeconds, durationSeconds, interruptible e spellID, disponíveis de forma independente, com remainingReason, durationReason, interruptibleReason ou spellReason quando um campo opcional está indisponível. Observações de presença ausentes, com falha ou restritas retornam nil com um motivo.",
-- 740dd187 English: Observe creature identity from native UnitCreatureType return two on probe- and
--     restricted-policy clients. Check exact UnitExists(unit) first; readable false returns false
--     without requiring or calling creature metadata. A present unit requires a readable finite
--     numeric ID; the unused localized name does not affect availability. Preserve signed,
--     fractional, zero and future finite IDs as known values. Missing, failed, nil, restricted or
--     malformed required facts return nil with a reason. No creature enumeration, translated
--     caption comparison or longterm cache is added.
[2810] = "Observa a identidade da criatura a partir do segundo retorno nativo de UnitCreatureType em clientes com política de sondagem ou restrita. Verifica primeiro exatamente UnitExists(unit); um false legível retorna false sem exigir nem chamar metadados de criatura. Uma unidade presente exige um ID numérico finito legível; o nome localizado não usado não afeta a disponibilidade. Preserva IDs com sinal, fracionários, zero e futuros finitos como valores conhecidos. Dados necessários ausentes, com falha, nil, restritos ou malformados retornam nil com um motivo. Nenhuma enumeração de criaturas, comparação de legendas traduzidas ou cache de longo prazo é adicionada.",
-- 075b71e7 English: Observe death or ghost state, or friendliness to the player, for the exact
--     selected unit on probe- and restricted-policy clients. A missing, failed, restricted or
--     malformed required observation is unavailable. Unit absence is unavailable rather than a
--     negative match, including under NOT. No cross-poll state is retained.
[2811] = "Observa o estado de morte ou fantasma, ou a amizade com o jogador, da unidade selecionada exata em clientes com política de sondagem ou restrita. Uma observação necessária ausente, com falha, restrita ou malformada fica indisponível. A ausência da unidade fica indisponível, em vez de ser uma correspondência negativa, inclusive sob NÃO. Nenhum estado é mantido entre consultas.",
-- 87176204 English: Observe exact pet existence and optionally its formatted GetUnitName display
--     name. Presence-only queries never require name data. Known absence skips the name query.
--     Present pets require a readable nonempty name only when requested; required missing, failed,
--     nil, restricted or malformed observations return nil with a reason. The display helper is
--     called with its single original pet argument, without UnitName fallback or inferred bar,
--     health or ability state.
[2812] = "Observa a existência exata do ajudante e, opcionalmente, o nome de exibição formatado de GetUnitName. Consultas apenas de presença nunca exigem dados de nome. Ausência conhecida pula a consulta do nome. Ajudantes presentes exigem um nome legível não vazio apenas quando solicitado; observações necessárias ausentes, com falha, nil, restritas ou malformadas retornam nil com um motivo. A função auxiliar de exibição é chamada com o único argumento original de ajudante, sem alternativa com UnitName nem estado deduzido de barra, vida ou habilidades.",
-- 2280ad22 English: Observe exact selected-unit existence and optionally its class filename for
--     point-resource conditions. Known absence returns exists=false without reading class. Present
--     units require only UnitClass return two when requested; unused localized names and IDs do not
--     affect availability. Required missing, failed, restricted or malformed observations remain
--     unavailable. This does not select a resource or cache identity.
[2813] = "Observa a existência exata da unidade selecionada e, opcionalmente, o nome de arquivo da classe dela para condições de recursos de pontos. Ausência conhecida retorna exists=false sem ler a classe. Unidades presentes exigem apenas o segundo retorno de UnitClass quando solicitado; nomes localizados e IDs não usados não afetam a disponibilidade. Observações necessárias ausentes, com falha, restritas ou malformadas continuam indisponíveis. Isso não seleciona um recurso nem guarda a identidade em cache.",
-- 9b79981c English: Observe explicit mana or the current raw power resource on supported readable
--     clients. Select resource identities from the live PowerType enum; explicit mana never falls
--     back to the current bar. Known absence returns exists=false; missing, failed, restricted or
--     malformed observations return nil with a reason. Current-mode quantities preserve signed
--     native resources; explicit mana is nonnegative. Request maximum only when needed; percentage
--     consumers must require a positive maximum.
[2814] = "Observa a mana explícita ou o recurso de poder bruto atual em clientes legíveis suportados. Seleciona as identidades de recurso a partir do enum PowerType ao vivo; a mana explícita nunca recorre à barra atual. Ausência conhecida retorna exists=false; observações ausentes, com falha, restritas ou malformadas retornam nil com um motivo. As quantidades do modo current preservam recursos nativos com sinal; a mana explícita é não negativa. Solicita o máximo apenas quando necessário; quem usa porcentagens deve exigir um máximo positivo.",
-- 278a17a4 English: Observe glyph sockets on verified Wrath, Cata and Mists client layouts. Returns
--     slots and a complete flag. Each slot has active=false when known locked or empty, active=true
--     plus spellID when occupied, or nil active plus reason when unavailable. Unknown layouts and
--     failed count queries return nil with a reason. This does not compare item names or prove
--     exact item-to-spell identity.
[2815] = "Observa os encaixes de glifos nos layouts de cliente verificados do Wrath, Cata e Mists. Retorna slots e um indicador complete. Cada encaixe tem active=false quando sabidamente bloqueado ou vazio, active=true mais spellID quando ocupado, ou active nil mais um motivo quando indisponível. Layouts desconhecidos e consultas de contagem com falha retornam nil com um motivo. Isso não compara nomes de itens nem prova a identidade exata de item para feitiço.",
-- 24ad932a English: Observe one consumed native unit metadata field after checking UnitExists:
--     class uses UnitClass return two, creature uses the localized UnitCreatureType name, and
--     classification uses UnitClassification. A readable absent unit returns false without querying
--     metadata. Unused tuple fields do not affect availability; a required missing, failed, nil,
--     restricted or malformed value returns nil with a reason. No player class, GUID, enum or
--     translation inference is added.
[2816] = "Observa um único campo de metadados nativos da unidade após verificar UnitExists: class usa o segundo retorno de UnitClass, creature usa o nome localizado de UnitCreatureType e classification usa UnitClassification. Uma unidade ausente legível retorna false sem consultar os metadados. Campos da tupla não usados não afetam a disponibilidade; um valor necessário ausente, com falha, nil, restrito ou malformado retorna nil com um motivo. Nenhuma dedução de classe do jogador, GUID, enum ou tradução é adicionada.",
-- 641cce1a English: Observe one current unit flag: combat uses UnitAffectingCombat, enemy uses
--     UnitIsEnemy with player as the first unit, and pvp uses UnitIsPVP. A readable absent unit
--     returns false without querying the flag. Required missing, failed, restricted or malformed
--     observations return nil with a reason. This preserves the exact selected unit and does not
--     infer friendliness, attackability or other unit states.
[2817] = "Observa um único indicador atual da unidade: combat usa UnitAffectingCombat, enemy usa UnitIsEnemy com player como primeira unidade e pvp usa UnitIsPVP. Uma unidade ausente legível retorna false sem consultar o indicador. Observações necessárias ausentes, com falha, restritas ou malformadas retornam nil com um motivo. Isso preserva a unidade selecionada exata e não deduz amizade, possibilidade de ataque nem outros estados da unidade.",
-- abc3ec81 English: Observe one exact native rune slot using GetRuneType with its single index
--     argument. Require a readable finite positive integral type; known future numeric types remain
--     distinct from the selected type, and Death is an exact type rather than a wildcard. Missing,
--     failed, restricted or malformed observations remain unavailable. No class, unit, count or
--     inferred base-rune query is added.
[2818] = "Observa um único espaço de runa nativo exato usando GetRuneType com o único argumento de índice. Exige um tipo inteiro positivo, finito e legível; tipos numéricos futuros conhecidos continuam distintos do tipo selecionado, e Morte é um tipo exato, não um curinga. Observações ausentes, com falha, restritas ou malformadas continuam indisponíveis. Nenhuma consulta de classe, unidade, contagem ou runa base deduzida é adicionada.",
-- 87dc4eea English: Observe one independent zero-argument player flag: stealthed uses IsStealthed,
--     control uses HasFullControl, and outdoors uses IsOutdoors. Readable true and false retain
--     their meanings. Required missing, failed, nil, restricted or malformed data returns nil with
--     a reason. No existence, instance or ability-usability inference is added.
[2819] = "Observa um único indicador independente do jogador sem argumentos: stealthed usa IsStealthed, control usa HasFullControl e outdoors usa IsOutdoors. Os valores legíveis true e false mantêm o significado. Dados necessários ausentes, com falha, nil, restritos ou malformados retornam nil com um motivo. Nenhuma dedução de existência, instância ou possibilidade de usar habilidades é adicionada.",
-- 46d51f29 English: Observe one protected zero-argument IsInInstance tuple. Required readable
--     Boolean membership is independent of the type field: known outside returns without
--     interpreting the unused type; inside returns a readable string type or an instanceTypeReason
--     when that secondary field is unavailable. Callers testing outside need only membership;
--     inside type comparisons must check the secondary reason. No outdoors, zone or unit inference
--     is added.
[2820] = "Observa uma única tupla protegida de IsInInstance sem argumentos. A participação booleana legível necessária independe do campo de tipo: fora (conhecido) retorna sem interpretar o tipo não usado; dentro retorna um tipo de texto legível ou um instanceTypeReason quando esse campo secundário está indisponível. Quem testa se está fora precisa apenas da participação; comparações de tipo dentro devem verificar o motivo secundário. Nenhuma dedução de ar livre, zona ou unidade é adicionada.",
-- 5671d2c8 English: Observe ordered selected-unit existence, hostility from player, then the player
--     threat status on that unit. Known absence, nonenemy and a successfully read nil threat status
--     return false, preserving the no-threat predicate. Finite status numbers including zero retain
--     their original comparison meaning. Required missing, failed, nil, restricted or malformed
--     facts return nil with a reason. No attackability, death, combat or vehicle inference is
--     added.
[2821] = "Observa em ordem a existência da unidade selecionada, a hostilidade a partir do jogador e depois o estado de ameaça do jogador sobre essa unidade. Ausência conhecida, não inimigo e um estado de ameaça nil lido com sucesso retornam false, preservando o predicado de sem ameaça. Números de estado finitos, incluindo zero, mantêm o significado de comparação original. Dados necessários ausentes, com falha, nil, restritos ou malformados retornam nil com um motivo. Nenhuma dedução de possibilidade de ataque, morte, combate ou veículo é adicionada.",
-- 545656e0 English: Observe readable current health and optionally maximum health on supported
--     clients. A readable absent unit returns exists=false. Missing, failed, restricted or
--     malformed observations return nil with a reason; they do not establish an absent unit or a
--     health value.
[2822] = "Observa a vida atual legível e, opcionalmente, a vida máxima em clientes suportados. Uma unidade ausente legível retorna exists=false. Observações ausentes, com falha, restritas ou malformadas retornam nil com um motivo; elas não estabelecem uma unidade ausente nem um valor de vida.",
-- 254b0aeb English: Observe the current player form with one protected zero-argument
--     GetShapeshiftForm call. Preserve every readable finite numeric result, including zero, signed
--     and fractional values; no stronger native index domain is inferred. Missing, failed, nil,
--     restricted or nonfinite data remains unavailable. No form count, class, spell ID, unit or
--     optional argument is added.
[2823] = "Observa a forma atual do jogador com uma única chamada protegida a GetShapeshiftForm sem argumentos. Preserva todos os resultados numéricos finitos legíveis, incluindo zero e valores com sinal e fracionários; nenhum domínio de índice nativo mais estrito é deduzido. Dados ausentes, com falha, nil, restritos ou não finitos continuam indisponíveis. Nenhuma contagem de formas, classe, ID de feitiço, unidade ou argumento opcional é adicionado.",
-- 1de1b681 English: Observe the effective statistic from native return two only. On probe- and
--     restricted-policy clients, query exact UnitExists(unit), then UnitStat(unit,stat) for
--     selector 1..5 or UnitArmor(unit) for selector 6. Known absence returns exists=false; missing,
--     failed, restricted or nonfinite required facts return nil. Preserve finite signed, fractional
--     and zero values; ignore all unused tuple fields. The 1..6 route is an RM selector policy, not
--     a native value-domain limit.
[2824] = "Observa o atributo efetivo apenas a partir do segundo retorno nativo. Em clientes com política de sondagem ou restrita, consulta exatamente UnitExists(unit) e depois UnitStat(unit,stat) para o seletor 1..5 ou UnitArmor(unit) para o seletor 6. Ausência conhecida retorna exists=false; dados necessários ausentes, com falha, restritos ou não finitos retornam nil. Preserva valores finitos com sinal, fracionários e zero; ignora todos os campos da tupla não usados. A rota 1..6 é uma política de seletor do RM, não um limite do domínio de valores nativo.",
-- 2cf23a04 English: Observe the explicitly selected TBC player combo transport. Current uses
--     exactly GetComboPoints(player,target); maximum uses UnitPowerMax(player,powerType) with the
--     original selector. Other families are unavailable here and must use their existing
--     point-power observer. Preserve readable finite signed, fractional and zero values. Missing,
--     failed, restricted or malformed data remains unavailable; a failed chosen combo query never
--     falls back to UnitPower. This observes no other actor and adds no cache.
[2825] = "Observa o transporte de combo do jogador do TBC selecionado explicitamente. Current usa exatamente GetComboPoints(player,target); maximum usa UnitPowerMax(player,powerType) com o seletor original. Outras famílias ficam indisponíveis aqui e devem usar o observador de poder de pontos existente. Preserva valores finitos legíveis com sinal, fracionários e zero. Dados ausentes, com falha, restritos ou malformados continuam indisponíveis; uma consulta de combo escolhida com falha nunca recorre a UnitPower. Não observa nenhum outro ator nem adiciona cache.",
-- 95b7963d English: Observe the first role result of the exact legacy GetTalentGroupRole(group) dot
--     call on probe- and restricted-policy clients. Forward the readable selected group unchanged,
--     including nil as one argument; do not infer group bounds, substitute another API or query a
--     player unit. The complete legacy primary declaration is not established. Missing, failed,
--     restricted, empty or malformed role data is unavailable; readable nonempty future strings
--     remain exact.
[2826] = "Observa o primeiro resultado de função da chamada com ponto exata e antiga GetTalentGroupRole(group) em clientes com política de sondagem ou restrita. Repassa sem alteração o grupo selecionado legível, incluindo nil como um argumento; não deduz os limites do grupo, não substitui outra API nem consulta uma unidade de jogador. A declaração principal antiga completa não é estabelecida. Dados de função ausentes, com falha, restritos, vazios ou malformados ficam indisponíveis; textos futuros legíveis e não vazios continuam exatos.",
-- 79e9c144 English: Observe the first zone PvP classification result with one protected
--     zero-argument dot call. Prefer callable C_PvP.GetZonePVPInfo and use the global helper only
--     when the modern callable is absent. A successful nil or no returned values produces a known
--     empty record; missing, failed, restricted or malformed observations remain unavailable.
--     Readable empty and future strings retain their exact meaning, and unused return fields do not
--     determine availability. Never switch backends after a modern result or failure.
[2827] = "Observa o primeiro resultado de classificação JxJ da zona com uma única chamada com ponto protegida e sem argumentos. Prefere a função invocável C_PvP.GetZonePVPInfo e usa a função global apenas quando a moderna não existe. Um nil bem-sucedido ou nenhum valor retornado produz um registro vazio conhecido; observações ausentes, com falha, restritas ou malformadas continuam indisponíveis. Textos legíveis vazios e futuros mantêm o significado exato, e campos de retorno não usados não determinam a disponibilidade. Nunca troca de backend após um resultado ou falha da moderna.",
-- 9570ca02 English: Observe the player current movement speed on supported readable clients. This
--     queries GetUnitSpeed for player only, without testing another unit or redirecting vehicle
--     ownership. Zero means stationary; positive finite fractional speeds remain valid. Missing,
--     failed, restricted or malformed observations return nil with a reason.
[2828] = "Observa a velocidade de movimento atual do jogador em clientes legíveis suportados. Consulta GetUnitSpeed apenas para player, sem testar outra unidade nem redirecionar a propriedade de veículos. Zero significa parado; velocidades positivas finitas fracionárias continuam válidas. Observações ausentes, com falha, restritas ou malformadas retornam nil com um motivo.",
-- 6b0f7980 English: Observe unit presence on identified client families. Pass the selected unit
--     unchanged to one protected UnitExists call. Preserve readable true and false; missing,
--     failed, restricted, nil or malformed required observations return nil with a reason. No
--     identity, visibility, range or combat-state query is added.
[2829] = "Observa a presença da unidade em famílias de cliente identificadas. Passa a unidade selecionada sem alteração para uma única chamada protegida a UnitExists. Preserva os valores legíveis true e false; observações necessárias ausentes, com falha, restritas, nil ou malformadas retornam nil com um motivo. Nenhuma consulta de identidade, visibilidade, alcance ou estado de combate é adicionada.",
-- a754c7d3 English: Observe whether the player can attack a selected unit that is not dead, using
--     the exact UnitExists, UnitCanAttack and UnitIsDead predicates. Known absence or a readable
--     false attack result returns false without querying death. Required missing, failed,
--     restricted or malformed observations return nil with a reason. This does not test ghosts,
--     range, hostility or ability usability, and does not redirect unit ownership.
[2830] = "Observa se o jogador pode atacar uma unidade selecionada que não esteja morta, usando exatamente os predicados UnitExists, UnitCanAttack e UnitIsDead. Ausência conhecida ou um resultado de ataque false legível retorna false sem consultar a morte. Observações necessárias ausentes, com falha, restritas ou malformadas retornam nil com um motivo. Isso não testa fantasmas, alcance, hostilidade nem possibilidade de usar habilidades, e não redireciona a propriedade da unidade.",
-- d4d5ab66 English: Observed class filename string, false for a known absent unit, or nil when
--     unavailable.
[2831] = "Texto do nome de arquivo de classe observado, false para unidade sabidamente ausente ou nil quando indisponível.",
-- 6b236c0f English: Observed membership, or nil when unavailable.
[2832] = "Participação observada, ou nil quando indisponível.",
-- 7c413887 English: On a selected resource only, target-combo for the explicit TBC player fallback
--     or power for the existing selected-unit transport.
[2833] = "Apenas em um recurso selecionado: target-combo para a alternativa explícita do jogador do TBC ou power para o transporte existente da unidade selecionada.",
-- 4b90146b English: On probe- and restricted-policy clients, observe exact UnitExists(unit), then
--     UnitGUID(unit) only for a present unit. Known absence is false. Present identity requires a
--     readable nonempty GUID; missing, failed, malformed or restricted required facts are
--     unavailable. No health, provider or extra-unit observation is added.
[2834] = "Em clientes com política de sondagem ou restrita, observa exatamente UnitExists(unit) e depois UnitGUID(unit) apenas para uma unidade presente. Ausência conhecida é false. A identidade presente exige um GUID legível e não vazio; dados necessários ausentes, com falha, malformados ou restritos ficam indisponíveis. Nenhuma observação de vida, de provedor ou de unidades extras é adicionada.",
-- 7980af82 English: One of class, creature or classification; other metadata kinds are unsupported.
[2835] = "Um de class, creature ou classification; outros tipos de metadados não são suportados.",
